"""AI Closed-Loop Auto-Remediation Schemas."""

from __future__ import annotations

from datetime import datetime
from typing import Literal
from pydantic import BaseModel, Field


class AIRemediationItem(BaseModel):
    """An autonomous or 1-click remediation recommendation generated by AI SRE."""

    id: str
    incident_id: int | None = None
    title: str
    category: Literal[
        "K8S_RESOURCE_BUMP",
        "DEPLOYMENT_ROLLBACK",
        "POD_RESTART",
        "CACHE_FLUSH",
        "AUTOSCALE",
    ]
    status: Literal["PENDING_APPROVAL", "EXECUTED", "REJECTED"] = "PENDING_APPROVAL"
    target_resource: str
    description: str
    confidence_score: float = Field(..., ge=0.0, le=1.0)
    before_state: str
    after_state: str
    rollback_guarantee: str
    created_at: datetime
    executed_at: datetime | None = None
    executed_by: str | None = None


class AIRemediationGenerateRequest(BaseModel):
    """Trigger AI generation of remediation proposals for an incident."""

    incident_id: int | None = None
    error_summary: str = Field(..., min_length=5, description="Error log or alert summary")
    service_name: str = Field(..., min_length=2, description="Target microservice or workload")


class AIRemediationActionRequest(BaseModel):
    """Approval or rejection request for a remediation proposal."""

    notes: str | None = Field(default=None, max_length=500)
